import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Data-Driven AST Child Roles — Closing the Last Engine Hardcoding","description":"","frontmatter":{"title":"Data-Driven AST Child Roles — Closing the Last Engine Hardcoding","type":"adr","date":"2026-09-04T00:00:00.000Z","status":"accepted","status_note":"Accepted. Phases 1–4 are implemented and the Phase 4 cross-language acceptance test passes (renamed kinds `set`/`block2`/`ret`/`params2`/`func2` with identical roles run through unchanged tree-walk and bytecode engines). Phase 5 (v1 deletion) remains coordinated with the [ADR-0052](./0052-arrow-calculus-kernel.md) cutover and is not blocking acceptance — the v2 engines are role-aware and the v1 path is no longer extended."},"headers":[],"relativePath":"handl/project/adrs/0081-data-driven-ast-child-roles.md","filePath":"vendored/handl/project/adrs/0081-data-driven-ast-child-roles.md"}'),a={name:`handl/project/adrs/0081-data-driven-ast-child-roles.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0081-data-driven-ast-child-roles-—-closing-the-last-engine-hardcoding" tabindex="-1">ADR-0081: Data-Driven AST Child Roles — Closing the Last Engine Hardcoding <a class="header-anchor" href="#adr-0081-data-driven-ast-child-roles-—-closing-the-last-engine-hardcoding" aria-label="Permalink to “ADR-0081: Data-Driven AST Child Roles — Closing the Last Engine Hardcoding”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>ADR-0058 (Accepted) migrated four primitives (<code>var</code>/<code>call</code>/<code>object</code>/pattern-match) to data and declared &quot;no new language-specific logic in engines.&quot; That claim holds for those four. But <code>eval_block</code>, <code>closure</code>, and typecheck shape dispatch still hardcode <code>kind ==</code> checks ADR-0058 didn&#39;t cover:</p><table tabindex="0"><thead><tr><th>Engine</th><th>Site</th><th>Hardcoded check</th></tr></thead><tbody><tr><td><code>plugin-engine-exec-tree-walk</code></td><td><code>closure</code></td><td><code>kind == &quot;paren&quot; || &quot;array&quot;</code> (1053)</td></tr><tr><td><code>plugin-engine-exec-tree-walk</code></td><td><code>closure</code> key</td><td><code>kind == &quot;var&quot; || &quot;string&quot;</code> (1249, 1259)</td></tr><tr><td><code>plugin-engine-exec-tree-walk</code></td><td><code>eval_block</code></td><td><code>kind == &quot;assign&quot;</code> (1544, 2283, 2352)</td></tr><tr><td><code>plugin-engine-exec-tree-walk</code></td><td><code>eval_block</code></td><td><code>kind == &quot;return&quot;</code> (2323)</td></tr><tr><td><code>plugin-engine-typecheck-nbe</code></td><td>synth/check</td><td><code>kind == &quot;type-annot&quot;</code> (884, 1109)</td></tr><tr><td><code>plugin-engine-typecheck-nbe</code></td><td>block</td><td><code>kind == &quot;block&quot;</code> (1247)</td></tr><tr><td><code>plugin-engine-typecheck-nbe</code></td><td>params</td><td><code>kind == &quot;paren&quot; || &quot;var&quot;</code> (1378, 1403, 3593)</td></tr><tr><td><code>plugin-engine-typecheck-nbe</code></td><td>block children</td><td><code>kind == &quot;assign&quot; || &quot;return&quot;</code> (2628, 2631, 2695)</td></tr></tbody></table><p>A primitive that needs &quot;the binding target of an <code>assign</code>&quot; can only get it by testing <code>kind == &quot;assign&quot;</code> and assuming child 0 is the target. A language with different kind names (<code>set</code> instead of <code>assign</code>, <code>params</code> instead of <code>paren</code>) can&#39;t reuse these primitives without engine edits — a breach of &quot;language as data&quot; (<a href="./0044-language-as-data-and-runtime-split.html">ADR-0044</a>).</p><p><code>AstShapeDef</code> has no child-role mechanism — children are referenced purely positionally via <code>proj_child(index)</code>. The role metadata lives only in engine Rust.</p><p>The closed native-op set (<code>add</code>/<code>sub</code>/<code>proj_child</code>/...) and the six kernel combinators are <strong>not</strong> violations — they&#39;re the engine&#39;s interpreter vocabulary. This ADR adds zero of either.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Add <strong>named child roles</strong> to <code>AstShapeDef</code>; resolve them to positional indices at assembly time. Engine, native-op set, and kernel combinators stay unchanged.</p><h3 id="_1-astshapedef-gains-optional-children" tabindex="-1">1. <code>AstShapeDef</code> gains optional <code>children</code> <a class="header-anchor" href="#_1-astshapedef-gains-optional-children" aria-label="Permalink to “1. AstShapeDef gains optional children”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">-</span><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;"> id</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> ast.assign</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  node_kind</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> assign</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  children</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">    -</span><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;"> role</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> target</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">    -</span><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;"> role</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> value</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">-</span><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;"> id</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> ast.block</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  node_kind</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> block</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  children</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">    -</span><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;"> role</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> statements</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">      variadic</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> true</span></span></code></pre></div><p><code>children: Option&lt;Vec&lt;ChildRoleSpec&gt;&gt;</code>. Absent = opaque, positional fallback (backward compatible). <code>variadic: true</code> resolves to <code>[start_index..]</code>.</p><h3 id="_2-proj-child-accepts-a-role-name" tabindex="-1">2. <code>proj_child</code> accepts a role name <a class="header-anchor" href="#_2-proj-child-accepts-a-role-name" aria-label="Permalink to “2. proj_child accepts a role name”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>arr_native_lit(&quot;proj_child&quot;, [], 0u64)        # positional (existing)</span></span>
<span class="line"><span>arr_native_lit(&quot;proj_child&quot;, [], &quot;target&quot;)    # by role (new)</span></span></code></pre></div><p>The <code>lit</code> payload is already <code>Value</code>; accepting <code>String</code> is a payload-shape extension, not a new op.</p><h3 id="_3-resolve-at-assembly-time-preferred" tabindex="-1">3. Resolve at assembly time (preferred) <a class="header-anchor" href="#_3-resolve-at-assembly-time-preferred" aria-label="Permalink to “3. Resolve at assembly time (preferred)”">​</a></h3><p><code>handl-kit-data-canonical</code> rewrites <code>proj_child(&quot;role&quot;)</code> → <code>proj_child(index)</code> by looking up the role in <code>AstShapeDef</code>. The runtime engine sees only positional <code>proj_child(u64)</code> — zero engine changes. (Fallback: runtime resolution in the <code>proj_child</code> handler if assembly-time proves awkward. Settled in Phase 1.)</p><h3 id="_4-rewrite-the-violating-primitives" tabindex="-1">4. Rewrite the violating primitives <a class="header-anchor" href="#_4-rewrite-the-violating-primitives" aria-label="Permalink to “4. Rewrite the violating primitives”">​</a></h3><p>Replace <code>kind ==</code> checks with role lookups. <code>eval_block</code> uses <code>proj_child(&quot;statements&quot;)</code>; each statement&#39;s own eval scheme handles binding vs return. <code>closure</code> uses <code>proj_child(&quot;params&quot;)</code>. Typecheck uses <code>synth_child(&quot;role&quot;)</code> / <code>check_child(&quot;role&quot;)</code>.</p><h3 id="_5-declare-roles-in-data-ast-yaml" tabindex="-1">5. Declare roles in <code>data/ast.yaml</code> <a class="header-anchor" href="#_5-declare-roles-in-data-ast-yaml" aria-label="Permalink to “5. Declare roles in data/ast.yaml”">​</a></h3><p>Add <code>children</code> to <code>assign</code>, <code>block</code>, <code>proc</code>/<code>function</code>, <code>paren</code>, <code>return</code>, <code>type-annot</code>.</p><h3 id="_6-acceptance-a-second-language" tabindex="-1">6. Acceptance: a second language <a class="header-anchor" href="#_6-acceptance-a-second-language" aria-label="Permalink to “6. Acceptance: a second language”">​</a></h3><p>Define a language with renamed kinds (<code>set</code>/<code>params</code>/<code>body</code>) but identical roles; run it through the <strong>unchanged</strong> engines. If they handle it without edits, the hardcoding is gone. Gate for marking this ADR Accepted.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p><strong>Positive:</strong> Closes the last engine hardcoding — &quot;language as data&quot; holds end-to-end. Zero kernel/native-op growth. Zero engine interpreter changes (under assembly-time resolution). Languages with different surface syntax reuse every engine without recompiles.</p><p><strong>Negative:</strong> <code>AstShapeDef</code> gains a field. Assembly pass gains a role-resolution step (unresolved role = load-time error). <code>proj_child</code> payload becomes polymorphic (<code>u64</code> | <code>string</code>). Eight hardcoded sites need mechanical rewrites in the most-tested crates.</p><p><strong>Neutral:</strong> Roles are per-shape, not global — <code>target</code> in <code>assign</code> is unrelated to <code>target</code> elsewhere. No global role registry; keeps the mechanism local.</p><h2 id="implementation-phases" tabindex="-1">Implementation phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to “Implementation phases”">​</a></h2><ol start="0"><li><strong>v2 audit</strong> — check v2 engines for the same <code>kind ==</code> pattern. Scopes the rest.</li><li><strong><code>AstShapeDef</code> roles + resolution</strong> — schema + assembly pass. Gate: <code>cargo test -p handl-language</code>.</li><li><strong>Migrate <code>data/ast.yaml</code></strong> — declare roles. Gate: <code>cargo test -p handl-kit-data-canonical</code>.</li><li><strong>Rewrite primitives</strong> — replace <code>kind ==</code> with role lookups; v2 only. Gate: existing tests pass unchanged.</li><li><strong>Cross-language test</strong> — renamed kinds, same roles, unchanged engines. Gate: passes → mark Accepted.</li><li><strong>v1 deletion</strong> — coordinated with ADR-0052 cutover. Gate: workspace builds without v1.</li></ol><h2 id="implementation-evidence" tabindex="-1">Implementation evidence <a class="header-anchor" href="#implementation-evidence" aria-label="Permalink to “Implementation evidence”">​</a></h2><p><strong>Phase 1–2</strong> (prior session): <code>AstShapeDef.children</code> / <code>ChildRoleSpec</code> schema added; <code>Language::child_role_index(kind, role)</code> resolver added; roles declared in <code>data/ast.yaml</code> for <code>assign</code>, <code>block</code>, <code>function</code>, <code>return</code>, <code>type-annot</code>, and others.</p><p><strong>Phase 3</strong> (this change): Replaced the remaining <code>kind == &quot;paren&quot; || kind == &quot;array&quot;</code> shape heuristics in the eval engines with <code>Language::has_variadic_role(kind)</code>, which inspects <code>AstShapeDef</code> role metadata. Sites converted:</p><ul><li><code>plugin-engine-exec-cranelift</code> — two closure param-list sites (runtime + helper).</li><li><code>plugin-engine-exec-bytecode</code> — <code>vm.rs</code> closure handler; <code>compile.rs</code> <code>try_extract_closure_params_body</code> (threaded <code>&amp;Language</code> through <code>compile</code>/<code>compile_into</code>/<code>compile_arr</code>).</li><li><code>handl-runtime/desugar_pass.rs</code> — <code>type-annot</code> detection now uses <code>child_role_index(kind, &quot;annot&quot;)</code> first (threaded <code>&amp;Language</code> through <code>try_rust_desugar</code>/<code>desugar_data</code>/<code>parse_data_payload</code>/<code>collect_constructors</code>/<code>desugar_match_to_recursor</code>).</li><li><code>plugin-ext-refinement/arrow_parser.rs</code> — binding detection now uses <code>child_role_index(kind, &quot;target&quot;)</code> first.</li><li><code>data/ast.yaml</code> — added <code>variadic: true</code> to <code>paren</code>&#39;s <code>body</code> role and a new <code>elements</code> variadic role to <code>array</code>, so collection-like shapes are detectable by role metadata alone.</li></ul><p>All legacy <code>kind ==</code> checks are retained only as fallbacks for role-less shapes (backward compatibility).</p><p><strong>Phase 4</strong> (this change): <code>crates/plugin-engine-exec-tree-walk/tests/adr0081_cross_language.rs</code> defines a language with renamed kinds (<code>set</code>/<code>block2</code>/<code>ret</code>/<code>params2</code>/<code>func2</code>) but identical roles and eval schemes, then runs it through the <strong>unchanged</strong> tree-walk and bytecode engines. Three tests cover block-with-binding and closure application. All pass — the engines handle renamed kinds without edits, satisfying the acceptance gate.</p><p><strong>Test results:</strong> <code>cargo test -p handl-plugin-engine-exec-tree-walk -p handl-plugin-engine-exec-bytecode -p handl-plugin-engine-exec-cranelift -p handl-language -p handl-runtime</code> — all pass (0 failures).</p><p><strong>Optional roles</strong> (this change): <code>ChildRoleSpec</code> gains <code>optional: true</code> for children that may be absent from a node — <code>match</code>&#39;s <code>motive</code> (<code>[scrutinee, (motive,) block]</code>) and <code>assign</code>&#39;s trailing <code>body</code> (<code>[target, value, (body)]</code>). Because optional slots make positions arity-dependent, resolution gains an arity-aware layer: <code>AstShapeDef::role_index_at(role, arity)</code>, <code>Language::child_role_index_for(node, role)</code> (arity from <code>payload[&quot;children&quot;]</code>), and <code>LanguageView::child_role_index_at(kind, role, arity)</code>. Occupied optional slots are the first <code>arity - required</code> optional roles in declaration order. <code>role_index</code>/<code>child_role_index</code> keep their full-form meaning (every declared role occupies a slot). <code>ChildRoleSpec</code> deserialization accepts a bare-string shorthand (<code>- scrutinee</code>) alongside the map form. <code>ast.yaml</code> declares the roles for <code>match</code>/<code>assign</code>; migrated consumers: tree-walk <code>prim_match</code> + <code>assign</code> arm, bytecode <code>prim_v2_match</code>, cranelift <code>prim_match</code>, arrow-lower&#39;s assign let-form, <code>desugar.match_recursor</code>, and the <code>role_child_arena</code> helpers / eval <code>Child</code> term (now arity-aware). Role-less positional fallbacks are retained for shapes declaring no roles.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0044-language-as-data-and-runtime-split.html">ADR-0044</a> — Language as Data.</li><li><a href="./0052-arrow-calculus-kernel.html">ADR-0052</a> — Arrow Calculus Kernel (fixed 6-combinator kernel).</li><li><a href="./0053-generic-pratt-parser.html">ADR-0053</a> — Generic Pratt Parser (desugar pass §7, prior <code>AstShapeDef</code> extension).</li><li><a href="./0054-generic-typecheck-engine.html">ADR-0054</a> — Generic Typecheck Engine.</li><li><a href="./0058-generic-data-driven-engines.html">ADR-0058</a> — Generic Data-Driven Engines (the scope this completes).</li><li><a href="./0059-generic-object-key-evaluation.html">ADR-0059</a>, <a href="./0060-generic-call-dispatch.html">ADR-0060</a>, <a href="./0061-generic-pattern-match.html">ADR-0061</a> — prior primitive migrations.</li><li><code>.devin/rules/engine-genericity.md</code> — always-on rule codifying this invariant.</li></ul>`,39)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};